import ActiveSection from "./components/ActiveSection.js";
import { initShaderCanvases } from "./components/ShaderCanvas.js";
import ImageViewer from "./components/ImageViewer.js";

class Main {
  constructor() {
    this.init();
  }

  init() {
    document.documentElement.classList.add("has-js");

    new ActiveSection();
    new ImageViewer();
    initShaderCanvases();
  }
}

const start = () => new Main();

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", start);
} else {
  start();
}
