/**
 * ImageViewer
 *
 * Finds every element with a `data-viewable` attribute, looks for an <img>
 * inside it, and injects a link into that element that opens the image in a
 * new tab (so the browser's native image viewer handles zooming).
 *
 * Markup:
 *   <div class="image__container" data-viewable>
 *     <img src="/img/artwork.jpg" alt="...">
 *   </div>
 *
 * Usage (in main.js):
 *   import { ImageViewer } from './image-viewer.js';
 *   new ImageViewer().init();
 *
 * Options:
 *   selector     - which containers to enhance      (default: '[data-viewable]')
 *   buttonClass  - class(es) put on the injected <a> (default: 'btn')
 *   label        - text inside the link              (default: 'View full size')
 */
export default class ImageViewer {
  constructor({
    selector = '[data-viewable]',
    buttonClass = '',
    label = '⛶',
  } = {}) {
    this.selector = selector;
    this.buttonClass = buttonClass;
    this.label = label;
    this.init();
  }

  init(root = document) {
    console.log("test")
    root.querySelectorAll(this.selector).forEach((container) => {
      this.#enhance(container);
    });
  }

  #enhance(container) {
    // Don't inject twice if init() is called more than once.
    if (container.querySelector('.image-viewer__link')) return;

    const img = container.querySelector('img');
    const src = img && (img.currentSrc || img.src);
    if (!src) return;

    const link = document.createElement('a');
    link.className = `image-viewer__link ${this.buttonClass}`.trim();
    link.href = src;
    link.target = '_blank';
    link.rel = 'noopener';
    link.textContent = this.label;
    link.setAttribute('aria-label', 'Open full-size image in new tab');

    container.appendChild(link);
  }
}